import { NotFoundError } from '@/domain/errors';
import type { Role } from '@/domain/roles';
import { db } from '@/server/db';
import { getStorage } from '@/server/storage';

/**
 * Teaser image of an opportunity.
 *
 * `Opportunity.teaserImage` holds the seed SVG as a base64 data URL
 * (`data:image/svg+xml;base64,...`, generated by the server, never by users).
 * An uploaded image (`teaserImageKey`, JPEG/PNG in S3) takes precedence and is
 * served through a 60 s signed URL.
 *
 * Visible when the opportunity is PUBLISHED, or to its seller and BACKOFFICE.
 * Anything else is a 404 so the response never reveals that the id exists.
 */
export type TeaserImageResult =
  | { kind: 'svg'; body: string }
  | { kind: 'redirect'; url: string };

const SVG_DATA_URL = /^data:image\/svg\+xml;base64,([A-Za-z0-9+/=]+)$/;

export function svgFromDataUrl(dataUrl: string): string | null {
  const m = SVG_DATA_URL.exec(dataUrl);
  return m?.[1] ? Buffer.from(m[1], 'base64').toString('utf8') : null;
}

function sniffImageType(key: string): string {
  return key.toLowerCase().endsWith('.png') ? 'image/png' : 'image/jpeg';
}

export async function resolveTeaserImage(
  viewer: { id: string; role: Role },
  opportunityId: string,
): Promise<TeaserImageResult> {
  const opp = await db.opportunity.findUnique({
    where: { id: opportunityId },
    select: { status: true, sellerId: true, teaserImage: true, teaserImageKey: true },
  });
  const allowed =
    opp &&
    (opp.status === 'PUBLISHED' || opp.sellerId === viewer.id || viewer.role === 'BACKOFFICE');
  if (!opp || !allowed) throw new NotFoundError();

  if (opp.teaserImageKey) {
    const url = await getStorage().presignGet(opp.teaserImageKey, 60, {
      contentType: sniffImageType(opp.teaserImageKey),
      disposition: 'inline',
    });
    return { kind: 'redirect', url };
  }
  const svg = opp.teaserImage ? svgFromDataUrl(opp.teaserImage) : null;
  if (!svg) throw new NotFoundError();
  return { kind: 'svg', body: svg };
}
